  const strip=document.querySelector('[data-route-updates]');strip.innerHTML=state.routeUpdates.length?'<details><summary>New opportunities available · '+state.routeUpdates.length+' route updates</summary>'+state.routeUpdates.map((u,i)=>'<button type="button" data-route-update="'+i+'">'+esc(hubs.find(h=>h.id===u.hub)?.name||'Quest')+' · '+u.activities.length+'</button>').join('')+'</details>':'';
  strip.querySelectorAll('[data-route-update]').forEach(button=>button.addEventListener('click',()=>{const u=state.routeUpdates[Number(button.dataset.routeUpdate)];state.noticeRead.push(u.id);state.routeUpdates=state.routeUpdates.filter(x=>x!==u);const h=hubs.find(h=>h.id===u.hub);for(const id of u.activities){const row=document.getElementById(h.id+'-'+id),group=row?.closest('details.activity-group');if(group){state.groupOpen[h.id+':'+group.dataset.activityGroup]=true;group.open=true;}row?.classList.add('new-opportunity');}persist();navigate('#whiteorchard-tree/'+h.id+'/'+u.activities[0]);}));

  toast.querySelector('button').hidden=!state.progressUndo;const undoLabel=state.progressUndo?.label?'Undo · '+state.progressUndo.label:'Undo last progress change';
